#!/usr/bin/env bash
# Долгая зима on Godot: the rules tests, the scenes headless, then the export to web/winter-godot/ (the engine goes
# to web/godot/, shared by every Godot game of the site).
#   GODOT=/path/to/godot-4.7.2 tools/winter-godot/build.sh
# Needs Godot 4.7.2 with its web export templates. The art is generated by tools/winter-godot/art (committed), so
# there is no bake step here; run `python3 tools/winter-godot/art/build_all.py` after changing a generator.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
GODOT="${GODOT:-godot}"

cd "$ROOT"
node tools/winter-godot/data.cjs --check
"$GODOT" --headless --path godot/winter --import >/dev/null 2>&1 || true
"$GODOT" --headless --path godot/winter -s res://tests/run.gd | tail -1
out="$("$GODOT" --headless --path godot/winter -s res://tests/scenes.gd 2>&1)"
echo "$out" | tail -1
if echo "$out" | grep -q "SCRIPT ERROR"; then echo "$out" | grep -A3 "SCRIPT ERROR" >&2; exit 1; fi
tools/godot-web/export.sh godot/winter web/winter-godot
